import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String userInputStr = scanner.nextLine();
        int counter = 0;
        String transformed = userInputStr.replace("at", "@").replace("dot", ".");
        char[] charsArray = transformed.toCharArray();
        int size = charsArray.length;

        if (size > 0) {
            if (charsArray[0] == '.') {
                charsArray[0] = 'd'; // placeholder for 'dot'
            }
            if (charsArray[size - 1] == '.') {
                charsArray[size - 1] = 'd'; // placeholder for 'dot'
            }
            if (charsArray[0] == '@') {
                charsArray[0] = 'a'; // placeholder for 'at'
            }
            if (charsArray[size - 1] == '@') {
                charsArray[size - 1] = 'a'; // placeholder for 'at'
            }
        }

        for (int i = 0; i < size; i++) {
            if (charsArray[i] == '@' && counter == 0) {
                counter = 1;
            } else if (charsArray[i] == '@') {
                charsArray[i] = 'a'; // placeholder for 'at'
            }
            System.out.print(charsArray[i]);
        }
        scanner.close();
    }
}
